package io.miragon.bpmn.adapter.outbound.codegen.builder.csharp.writer

import io.miragon.bpmn.adapter.outbound.codegen.PackagePath
import io.miragon.bpmn.adapter.outbound.codegen.SourceCode
import io.miragon.bpmn.domain.GeneratedFileHeader

/**
 * Renders C# types as the source text of a generated file. The file is marked `<auto-generated/>` and
 * opts into nullable annotations itself, because Roslyn treats generated files as nullable-disabled regardless of
 * the project, so it compiles under any consumer settings.
 */
internal object CSharpSourceFile {

    fun render(packagePath: PackagePath, writeTypes: (CSharpWriter) -> Unit): SourceCode {
        val writer = CSharpWriter()
        writer.line("// <auto-generated/>")
        writer.line(GeneratedFileHeader.LINE)
        writer.line("#nullable enable")
        writer.line("#pragma warning disable CS1591")
        writer.line("namespace ${packagePath.value};")
        writer.line()
        writeTypes(writer)
        return SourceCode(writer.render())
    }
}
